   655  static mrb_int
   656  mrb_memsearch(const char *x, mrb_int m, const char *y, mrb_int n)
   657  {
   658    if (m > n) return -1;
   659    else if (m == n) {
   660      return memcmp(x, y, m) == 0 ? 0 : -1;
   661    }
   662    else if (m < 1) {
   663      return 0;
   664    }
   665    else if (m == 1) {
   666      const char *p = (const char*)memchr(y, *x, n);
   667
   668      if (p) return (mrb_int)(p - y);
   669      return -1;
   670    }
   671    return memsearch_swar(x, m, y, n);
   672  }
